var e={"devices.feature.title":`デバイス`,"devices.feature.desc":`Claudeがお使いのパソコンやスマートフォンを操作します。画面を見て、クリックや入力をし、アプリを開きます。いつでも様子を確認して、操作を引き継げます。`,"devices.feature.enable":`自分のデバイスを使う`,"devices.feature.enableDesc":`Harness Linkアプリでパソコン（Windows、Mac、Linux）またはAndroidスマートフォンを接続します。セッションは許可したデバイスを使えます。エージェントは、そのエージェント用にオンにしたデバイスのみ使えます。`,"devices.openPage":`デバイスを開く`,"devices.openPageHint":`デバイスを追加し、Claudeに許可する操作を選びます。`,"devices.settingsDesc":`Claudeが使えるパソコンとスマートフォン`,"devices.add":`デバイスを追加`,"devices.add.desc":`パソコンではコマンドを実行し、スマートフォンではリンクを開きます。コードは1回のみ、15分間有効です。`,"devices.add.windows":`Windows`,"devices.add.mac":`Mac`,"devices.add.linux":`Linux`,"devices.add.android":`Android`,"devices.add.cmdWindows":`PCでPowerShellを開き（スタートメニューで「PowerShell」と入力）、次を貼り付けます：`,"devices.add.cmdMac":`MacでTerminalを開き（Spotlightで「Terminal」と入力）、次を貼り付けます：`,"devices.add.cmdLinux":`ターミナルを開いて貼り付けます。X11は完全に動作します。Waylandデスクトップにはまだ対応していません（ログイン時にX11セッションを選んでください）。`,"devices.add.macHelp":`macOSの「画面収録」と「アクセシビリティ」の権限は、Harness Linkではなくターミナルアプリに付与されます。システム設定 -> プライバシーとセキュリティの両方でTerminal（またはiTermなど）をオンにし、終了（cmd+Q）して開き直し、harness-link と入力してください。`,"devices.add.phone":`スマートフォンのカメラでこのコードをスキャンします。ページでアプリをダウンロードしてインストールし、「Open in Harness Link」をタップします。`,"devices.add.phoneHelp":`その後、Harness Linkがアクセシビリティサービスのオンを求めます。これにより、Claudeのために画面を見てタップできるようになります。`,"devices.add.apk":`アプリをダウンロード（APK）`,"devices.add.apkHelp":`カメラが手元にありませんか？コードの下のボタンからアプリを直接ダウンロードできます。スマートフォンでこのページを開いてタップするか、ファイルをスマートフォンにコピーしてください。`,"devices.add.manual":`またはHarness Linkに次を入力します：`,"devices.add.server":`サーバー`,"devices.add.code":`コード`,"devices.add.secret":`コマンドにはコードが含まれています。共有しないでください。`,"devices.add.expires":`あと{time}で期限切れ`,"devices.add.expired":`このコードは期限切れです。`,"devices.add.again":`新しいコード`,"devices.add.waiting":`デバイスを待っています…`,"devices.add.ready":`{name}が接続されました`,"devices.add.readyDesc":`承認されました。Harness Linkがターミナルウィンドウで動作している間、Claudeはこのパソコンを使えます。行で「表示のみ」または「操作」を選んでください。`,"devices.add.readyPhone":`承認されました。Harness Linkがオンの間、Claudeはこのスマートフォンを使えます。行で「表示のみ」または「操作」を選んでください。`,"devices.add.done":`完了`,"devices.live.screen":`画面`,"devices.live.screenHelp":`Claudeがこのパソコンで見て使う画面です。「見る」にも表示されます。別の画面が必要な場合は、Claude自身で切り替えられます。`,"devices.live.main":`メイン`,"devices.add.notAvailable":`Harness Linkは、このサーバーではまだダウンロードできません。`,"devices.new.title":`新しいデバイス：{name}（{os}）`,"devices.new.desc":`{ip}から、あなたのコードのひとつが使われました。ご自身のデバイスですか？承認するまで、Claudeはこのデバイスを使えません。心当たりがない場合は拒否してください。接続が切断され、このサーバーの情報も削除されます。`,"devices.accept":`承認`,"devices.refuse":`拒否`,"devices.empty":`デバイスはまだありません。パソコンやスマートフォンを追加すると、Claudeがそのアプリを使えるようになります。`,"devices.online":`オンライン`,"devices.offline":`オフライン · 最終確認 {ago}`,"devices.paused":`デバイスで一時停止中`,"devices.human":`あなたが操作中`,"devices.claude":`Claudeが使用中`,"devices.mode.label":`Claudeに許可する操作`,"devices.mode.view":`表示のみ`,"devices.mode.control":`操作`,"devices.mode.viewDesc":`Claudeは画面を見て案内しますが、クリックや入力は一切しません。`,"devices.access.label":`使用できる対象`,"devices.access.all":`すべてのプロジェクトとエージェント`,"devices.access.some":`選んだプロジェクト`,"devices.access.none":`現在は誰も使えません`,"devices.access.count":`{count}件のプロジェクト`,"devices.access.count#one":`{count}件のプロジェクト`,"devices.access.agentsNote":`エージェントは、そのエージェントの設定（エージェントのページ -> デバイス）でもデバイスをオンにする必要があります。`,"devices.watch":`見る`,"devices.rename":`名前を変更`,"devices.rename.title":`デバイスの名前を変更`,"devices.remove":`削除`,"devices.remove.title":`{name}を削除しますか？`,"devices.remove.desc":`Claudeはこのデバイスを使用できなくなります。そのデバイス上の Harness Link はこのサーバーを忘れて停止します。`,"devices.note":`デバイスからのメッセージ：{note}`,"devices.add.after":`Harness Link はそのウィンドウで動作し、Claudeの操作内容を表示します。次回以降は、ターミナルで harness-link と入力してください。Claudeがコンピューターを使用できるのは、そのウィンドウが開いている間だけです（Ctrl+C で停止します）。`,"devices.offlineHelp":`Claudeに使用させるには、そのデバイスのターミナルで harness-link と入力してください。`,"devices.offlineHelp.android":`Claudeに使用させるには、スマートフォンで Harness Link を開いてください。`,"devices.outdated":`新しいバージョンの Harness Link があります（{version}）。更新するには、デバイスをもう一度追加してください。`,"devices.actions.title":`最近の操作`,"devices.more":`その他`,"devices.list.title":`お使いのデバイス`,"devices.list.count":`お使いのデバイス（{count}）`,"devices.actions.desc":`Claudeがお使いのデバイスで行った操作です。入力したテキストは保存されず、文字数のみ記録されます。`,"devices.actions.removed":`削除されたデバイス`,"devices.actions.more":`もっと見る`,"devices.actions.less":`閉じる`,"devices.act.click":`({x}, {y}) をクリックしました`,"devices.act.double":`({x}, {y}) をダブルクリックしました`,"devices.act.type":`{count}文字を入力しました`,"devices.act.type#one":`{count}文字を入力しました`,"devices.act.key":`{keys} を押しました`,"devices.act.open":`アプリを開きました`,"devices.act.openNamed":`{name}を開きました`,"devices.act.wait":`{s}秒待機しました`,"devices.act.screen":`画面{n}に切り替えました`,"devices.act.screenshot":`画面を確認しました`,"devices.act.zoom":`ズームしました`,"devices.act.scroll":`スクロールしました`,"devices.act.drag":`ドラッグしました`,"devices.act.move":`ポインターを移動しました`,"devices.act.long_press":`長押ししました`,"devices.act.ui_tree":`画面の要素を読み取りました`,"devices.act.tap_element":`要素をタップしました`,"devices.act.set_text":`フィールドに入力しました`,"devices.act.apps":`アプリの一覧を取得しました`,"devices.act.ask_human":`操作をお願いしました`,"devices.act.devices":`デバイスの一覧を取得しました`,"devices.live.title":`{name}のライブ画面`,"devices.live.desc":`デバイスの画面をライブで表示します。タッチすると操作を引き継げます。一言添えてClaudeに戻せます。`,"devices.live.take":`操作を引き継ぐ`,"devices.live.handBack":`操作を戻す`,"devices.live.word":`Claudeへの一言（任意）`,"devices.live.done":`完了、操作を戻す`,"devices.live.skip":`このステップをスキップ`,"devices.live.youHave":`現在はあなたが操作中です。操作を戻すまでClaudeは待機します。`,"devices.live.claudeHas":`Claudeが使用中です。画像をタッチすると操作を引き継げます。`,"devices.live.viewOnly":`表示のみ：Claudeは見るだけで、操作しません。`,"devices.live.offline":`デバイスはオフラインです。Harness Link が起動していないか、デバイスがスリープ中です。`,"devices.live.paused":`デバイスで Harness Link が一時停止中です。`,"devices.live.connecting":`接続中…`,"devices.live.back":`戻る`,"devices.live.home":`ホーム`,"devices.live.recents":`最近使ったアプリ`,"devices.live.type":`ここに入力、Enter で送信`,"devices.live.close":`閉じる`,"devices.live.ask":`Claudeからのお願い：{message}`,"devices.bar.using":`Claudeが{name}を使用中`,"devices.bar.watch":`見る`,"devices.ask.title":`{name}：Claudeがあなたの操作を必要としています。`,"devices.ask.open":`開く`,"devices.ask.skip":`スキップ`,"devices.agent.title":`デバイス`,"devices.agent.none":`このエージェントのプロジェクトを許可しているデバイスはまだありません（設定 -> デバイス -> 使用できるユーザー）。`,"devices.agent.hint":`このエージェントが使用できるデバイスです。初期状態ではオフです。`};export{e as default};